-- V1 — Baseline schema (2026-11-04)
--
-- What: every table GitBase had when Flyway was switched on, exactly as the JPA entities map them
--       (generated by Hibernate on an empty database, dumped with pg_dump, schema prefix removed).
-- Why:  until now the schema came from `ddl-auto: update`, which never drops, renames or backfills
--       anything and leaves no record of what changed. From here on every change is a versioned
--       migration and Hibernate only validates (`ddl-auto: validate`).
-- Impact: none on existing databases — they are baselined at version 1 (`baseline-on-migrate`), so
--       this script only runs on an empty database. Constraint names are Hibernate's deterministic
--       ones, identical to those in databases created by `ddl-auto`, so later migrations can name them.
--
-- Not here on purpose: no commits / branches / tags tables — git is the source of truth (DECISION-007).


CREATE TABLE activities (
    id bigint NOT NULL,
    "timestamp" timestamp(6) without time zone NOT NULL,
    description character varying(1000),
    actor character varying(255) NOT NULL,
    target character varying(255) NOT NULL,
    type character varying(255) NOT NULL,
    CONSTRAINT activities_type_check CHECK (((type)::text = ANY ((ARRAY['COMMIT'::character varying, 'PUSH'::character varying, 'PULL_REQUEST'::character varying, 'CODE_REVIEW'::character varying, 'REPO_CREATED'::character varying, 'REPO_UPDATED'::character varying, 'REPO_DELETED'::character varying, 'TOKEN_CREATED'::character varying, 'TOKEN_REVOKED'::character varying])::text[])))
);

ALTER TABLE activities ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME activities_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE auth_refresh_tokens (
    created_at timestamp(6) with time zone NOT NULL,
    expires_at timestamp(6) with time zone NOT NULL,
    id bigint NOT NULL,
    used_at timestamp(6) with time zone,
    session_id uuid NOT NULL,
    token_hash character varying(64) NOT NULL
);

ALTER TABLE auth_refresh_tokens ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME auth_refresh_tokens_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE auth_sessions (
    created_at timestamp(6) with time zone NOT NULL,
    expires_at timestamp(6) with time zone NOT NULL,
    revoked_at timestamp(6) with time zone,
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    revoke_reason character varying(32)
);

CREATE TABLE git_tokens (
    created_at timestamp(6) without time zone,
    expires_at timestamp(6) without time zone,
    id bigint NOT NULL,
    user_id uuid NOT NULL,
    name character varying(255),
    scopes character varying(255),
    token_hash character varying(255)
);

ALTER TABLE git_tokens ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME git_tokens_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE issue_assignees (
    issue_id bigint NOT NULL,
    user_id uuid NOT NULL
);

CREATE TABLE issue_comments (
    created_at timestamp(6) without time zone NOT NULL,
    id bigint NOT NULL,
    issue_id bigint NOT NULL,
    updated_at timestamp(6) without time zone,
    author_id uuid NOT NULL,
    body text NOT NULL
);

ALTER TABLE issue_comments ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME issue_comments_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE issue_dependencies (
    created_at timestamp(6) without time zone NOT NULL,
    dependency_id bigint NOT NULL,
    id bigint NOT NULL,
    issue_id bigint NOT NULL,
    created_by_id uuid
);

ALTER TABLE issue_dependencies ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME issue_dependencies_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE issue_labels (
    issue_id bigint NOT NULL,
    label_id bigint NOT NULL
);

CREATE TABLE issues (
    closed_by_pull_number integer,
    number integer NOT NULL,
    closed_at timestamp(6) without time zone,
    created_at timestamp(6) without time zone NOT NULL,
    id bigint NOT NULL,
    updated_at timestamp(6) without time zone,
    author_id uuid NOT NULL,
    closed_by_id uuid,
    repository_id uuid NOT NULL,
    state character varying(20) NOT NULL,
    body text,
    title character varying(255) NOT NULL,
    CONSTRAINT issues_state_check CHECK (((state)::text = ANY ((ARRAY['OPEN'::character varying, 'CLOSED'::character varying])::text[])))
);

ALTER TABLE issues ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME issues_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE labels (
    color character varying(6) NOT NULL,
    id bigint NOT NULL,
    repository_id uuid NOT NULL,
    name character varying(100) NOT NULL,
    description character varying(255)
);

ALTER TABLE labels ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME labels_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE pipeline_executions (
    duration bigint,
    finished_at timestamp(6) without time zone,
    id bigint NOT NULL,
    repository_id bigint,
    started_at timestamp(6) without time zone,
    branch character varying(255),
    commit_sha character varying(255),
    status character varying(255),
    pipeline_config oid,
    CONSTRAINT pipeline_executions_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'RUNNING'::character varying, 'SUCCESS'::character varying, 'FAILED'::character varying, 'CANCELLED'::character varying])::text[])))
);

ALTER TABLE pipeline_executions ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME pipeline_executions_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE pipeline_stage_executions (
    exit_code integer,
    finished_at timestamp(6) without time zone,
    id bigint NOT NULL,
    pipeline_execution_id bigint,
    started_at timestamp(6) without time zone,
    docker_image character varying(255),
    stage_name character varying(255),
    status character varying(255),
    logs oid,
    CONSTRAINT pipeline_stage_executions_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'RUNNING'::character varying, 'SUCCESS'::character varying, 'FAILED'::character varying, 'CANCELLED'::character varying])::text[])))
);

ALTER TABLE pipeline_stage_executions ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME pipeline_stage_executions_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE pull_request_comments (
    created_at timestamp(6) without time zone NOT NULL,
    id bigint NOT NULL,
    pull_request_id bigint NOT NULL,
    updated_at timestamp(6) without time zone,
    author_id uuid NOT NULL,
    body text NOT NULL
);

ALTER TABLE pull_request_comments ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME pull_request_comments_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE pull_requests (
    number integer NOT NULL,
    closed_at timestamp(6) without time zone,
    created_at timestamp(6) without time zone NOT NULL,
    id bigint NOT NULL,
    merged_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    version bigint DEFAULT 0,
    author_id uuid NOT NULL,
    merge_method character varying(16),
    merged_by_id uuid,
    repository_id uuid NOT NULL,
    status character varying(20) NOT NULL,
    base_sha character varying(40),
    head_sha character varying(40),
    merge_commit_sha character varying(40),
    description text,
    source_branch character varying(255) NOT NULL,
    target_branch character varying(255) NOT NULL,
    title character varying(255) NOT NULL,
    CONSTRAINT pull_requests_merge_method_check CHECK (((merge_method)::text = ANY ((ARRAY['MERGE'::character varying, 'SQUASH'::character varying, 'REBASE'::character varying])::text[]))),
    CONSTRAINT pull_requests_status_check CHECK (((status)::text = ANY ((ARRAY['OPEN'::character varying, 'CLOSED'::character varying, 'MERGED'::character varying])::text[])))
);

ALTER TABLE pull_requests ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME pull_requests_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE repositories (
    is_private boolean NOT NULL,
    last_issue_number integer DEFAULT 0,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    repo_name character varying(255) NOT NULL
);

CREATE TABLE repository_collaborators (
    created_at timestamp(6) without time zone NOT NULL,
    updated_at timestamp(6) without time zone,
    id uuid NOT NULL,
    repository_id uuid NOT NULL,
    user_id uuid NOT NULL,
    permission character varying(20) NOT NULL,
    CONSTRAINT repository_collaborators_permission_check CHECK (((permission)::text = ANY ((ARRAY['READ'::character varying, 'WRITE'::character varying, 'ADMIN'::character varying])::text[])))
);

CREATE TABLE t_role (
    id bigint NOT NULL,
    role_name character varying(255)
);

CREATE SEQUENCE t_role_seq
    START WITH 1
    INCREMENT BY 50
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE t_users (
    account_locked boolean,
    email_verified boolean,
    is_enabled boolean NOT NULL,
    created_at timestamp(6) without time zone,
    last_login timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    account_type character varying(16) DEFAULT 'USER'::character varying,
    id uuid NOT NULL,
    description character varying(500),
    auth_provider character varying(255),
    email character varying(255) NOT NULL,
    full_name character varying(255),
    google_id character varying(255),
    name character varying(255) NOT NULL,
    password character varying(255),
    profile_picture_url character varying(255),
    CONSTRAINT t_users_account_type_check CHECK (((account_type)::text = ANY ((ARRAY['USER'::character varying, 'ORGANIZATION'::character varying])::text[]))),
    CONSTRAINT t_users_auth_provider_check CHECK (((auth_provider)::text = ANY ((ARRAY['GOOGLE'::character varying, 'LOCAL'::character varying])::text[])))
);

CREATE TABLE team_members (
    created_at timestamp(6) without time zone NOT NULL,
    id bigint NOT NULL,
    team_id bigint NOT NULL,
    user_id uuid NOT NULL
);

ALTER TABLE team_members ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME team_members_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE team_repositories (
    created_at timestamp(6) without time zone NOT NULL,
    id bigint NOT NULL,
    team_id bigint NOT NULL,
    repository_id uuid NOT NULL
);

ALTER TABLE team_repositories ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME team_repositories_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE teams (
    can_create_org_repo boolean NOT NULL,
    includes_all_repositories boolean NOT NULL,
    owner_team boolean NOT NULL,
    created_at timestamp(6) without time zone NOT NULL,
    id bigint NOT NULL,
    permission character varying(10) NOT NULL,
    organization_id uuid NOT NULL,
    lower_name character varying(100) NOT NULL,
    name character varying(100) NOT NULL,
    description character varying(500),
    CONSTRAINT teams_permission_check CHECK (((permission)::text = ANY ((ARRAY['READ'::character varying, 'WRITE'::character varying, 'ADMIN'::character varying])::text[])))
);

ALTER TABLE teams ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME teams_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE user_roles (
    role_id bigint NOT NULL,
    user_id uuid NOT NULL
);

